The InfiniteLoader component accepts the same props as the useInfiniteLoader hook and passes the onRowsRendered callback to a render prop. import { useCallback, useState } from "react";
import { List } from "react-window";
import { InfiniteLoader } from "react-window-infinite-loader";

const ROW_COUNT = 1_000;

function Example() {
 const [rows, setRows] = useState(() => new Map<number, string>());

 const isRowLoaded = useCallback((index: number) => rows.has(index), [rows]);

 const loadMoreRows = useCallback(
 async (startIndex: number, stopIndex: number) => {
 // fetchRows loads a range of rows (e.g. from a server)
 const loadedRows = await fetchRows(startIndex, stopIndex);

 setRows((prev) => {
 const next = new Map(prev);
 loadedRows.forEach((row, offset) => next.set(startIndex + offset, row));
 return next;
 });
 },
 []
 );

 return (
 <InfiniteLoader
 isRowLoaded={isRowLoaded}
 loadMoreRows={loadMoreRows}
 rowCount={ROW_COUNT}
 >
 {({ onRowsRendered }) => (
 <List
 onRowsRendered={onRowsRendered}
 rowComponent={RowComponent}
 rowCount={ROW_COUNT}
 rowHeight={25}
 rowProps={{ rows }}
 />
 )}
 </InfiniteLoader>
 );
} Continue to InfiniteLoader props…

The useInfiniteLoader hook returns an onRowsRendered callback to pass to a react-window List. As rows are scrolled into view, it calls loadMoreRows for any that have not been loaded yet. Scroll the list below to try it out: import { useCallback, useState } from "react";
import { List } from "react-window";
import { useInfiniteLoader } from "react-window-infinite-loader";

const ROW_COUNT = 1_000;

function Example() {
 const [rows, setRows] = useState(() => new Map<number, string>());

 const isRowLoaded = useCallback((index: number) => rows.has(index), [rows]);

 const loadMoreRows = useCallback(
 async (startIndex: number, stopIndex: number) => {
 // fetchRows loads a range of rows (e.g. from a server)
 const loadedRows = await fetchRows(startIndex, stopIndex);

 setRows((prev) => {
 const next = new Map(prev);
 loadedRows.forEach((row, offset) => next.set(startIndex + offset, row));
 return next;
 });
 },
 []
 );

 const onRowsRendered = useInfiniteLoader({
 isRowLoaded,
 loadMoreRows,
 rowCount: ROW_COUNT
 });

 return (
 <List
 onRowsRendered={onRowsRendered}
 rowComponent={RowComponent}
 rowCount={ROW_COUNT}
 rowHeight={25}
 rowProps={{ rows }}
 />
 );
} Rows that have not loaded yet can render a placeholder: import type { RowComponentProps } from "react-window";

function RowComponent({
 index,
 rows,
 style
}: RowComponentProps<{ rows: Map<number, string> }>) {
 return (
 <div className="flex items-center px-2" style={style}>
 {rows.get(index) ?? <span className="text-slate-500">Loading…</span>}
 </div>
 );
} Rows are not requested again while a request for them is in progress. Once the Promise returned by loadMoreRows settles, rows that are still not loaded (e.g. because the request failed) will be requested again the next time they are rendered. Continue to useInfiniteLoader parameters…

